#include "SynthPresets.h"
#include <set>
static void testSynths(const File& root,Assets& assets){
    const auto& factory=factorySynthPresets();expect(factory.size()==72,"seventy-two original factory synth sounds are bundled offline");std::set<String> names;int analog=0,fm=0;std::vector<double> fingerprints;
    for(const auto& preset:factory){expect(validateSynthPreset(preset).wasOk(),("valid sound: "+preset.name).toRawUTF8());names.insert(preset.name);analog+=preset.instrument==Instrument::analog;fm+=preset.instrument==Instrument::fm;
        auto song=emptyProject();song.bpm=120;song.loop=false;song.tracks[7].instrument=preset.instrument;song.tracks[7].synth=preset.patch;song.tracks[7].attack=preset.attack;song.tracks[7].release=preset.release;song.tracks[7].send=0;song.patterns[0].lanes[7]={{0,.6,60,.8f}};auto audio=render(song,assets,root,24000,127);bool finite=true;double fingerprint=0;for(int i=0;i<24000;++i){finite&=std::isfinite(audio.getSample(0,i));fingerprint+=audio.getSample(0,i)*(1+(i%997));}expect(finite&&audio.getMagnitude(0,0,24000)>.0001f,("audible finite sound: "+preset.name).toRawUTF8());fingerprints.push_back(fingerprint);
        SynthPreset read;expect(synthPresetFromJson(synthPresetToJson(preset),read).wasOk()&&read.patch==preset.patch&&read.attack==preset.attack&&read.release==preset.release&&read.instrument==preset.instrument,("complete patch roundtrip: "+preset.name).toRawUTF8());}
    expect(names.size()==72&&analog==24&&fm==16,"factory sounds have unique names across five engines");bool distinct=true;for(size_t a=0;a<fingerprints.size();++a)for(size_t b=a+1;b<fingerprints.size();++b)distinct&=std::abs(fingerprints[a]-fingerprints[b])>.00001;expect(distinct,"all seventy-two factory sounds produce distinct audio fingerprints");
    auto song=emptyProject();song.loop=false;song.bpm=120;auto& t=song.tracks[7];t.instrument=Instrument::analog;t.synth=factory[7].patch;t.send=0;song.patterns[0].lanes[7]={{0,.8,60,.6f},{.1,.7,64,.7f},{.2,.6,67,.8f}};auto a=render(song,assets,root,48000,127),b=render(song,assets,root,48000,512);bool equal=true;for(int ch=0;ch<2;++ch)for(int i=0;i<48000;++i)equal&=a.getSample(ch,i)==b.getSample(ch,i);expect(equal,"polyphonic synth render is independent of audio callback size");
    t.instrument=Instrument::fm;t.synth=factory[28].patch;a=render(song,assets,root,48000,127);b=render(song,assets,root,48000,512);equal=true;for(int ch=0;ch<2;++ch)for(int i=0;i<48000;++i)equal&=a.getSample(ch,i)==b.getSample(ch,i);expect(equal,"FM render is independent of callback size");
    SynthPatch sine;sine.wave1=sine.wave2=0;sine.mix=0;sine.sub=0;sine.detune=0;sine.cutoff=18000;sine.sustain=1;sine.decay=.01f;
    for(double rate:{22050.,44100.,48000.,96000.}){SynthVoice voice;voice.start(69,rate,123);int crossings=0;float previous=0;for(int i=0;i<(int)rate;++i){float sample=voice.process(sine,false,true,.001f,.02f);if(i>(int)(rate*.1)&&previous<=0&&sample>0)++crossings;previous=sample;}expect(crossings>=394&&crossings<=397,"A4 synth oscillator remains tuned across sample rates");}
    SynthVoice voice;voice.start(60,48000,123);for(int i=0;i<4800;++i)voice.process(sine,false,true,.001f,.05f);for(int i=0;i<3000;++i)voice.process(sine,false,false,.001f,.05f);expect(!voice.active()&&voice.process(sine,false,false,.001f,.05f)==0,"note-off ends a voice after its release interval");
    bool stable=true;for(double rate:{8000.,22050.,48000.,192000.})for(int pitch:{0,60,127})for(bool fmMode:{false,true}){SynthPatch extreme;extreme.resonance=1;extreme.cutoff=20000;extreme.filterEnv=6;extreme.filterDecay=.01f;extreme.fmIndex=12;extreme.fmRatio=16;extreme.lfoPitch=100;extreme.lfoRate=20;extreme.lfoFilter=4;extreme.noise=.5f;extreme.sub=1;voice.start(pitch,rate,999);for(int i=0;i<12000;++i){float v=voice.process(extreme,fmMode,i<8000,.001f,.02f);stable&=std::isfinite(v)&&std::abs(v)<=.56f;}}expect(stable,"extreme pitch, resonance, FM and modulation remain finite and bounded at supported rates");
    auto engine=makeEngine(song,assets,root);engine->stop();AudioBuffer<float> block(2,512);for(int i=0;i<128;++i)expect(engine->audition(7,36+i%60,true,.7f,.1f),"bounded synth audition queue accepts polyphony stress");for(int i=0;i<100;++i)engine->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(std::isfinite(block.getMagnitude(0,0,512)),"maximum-polyphony synth rendering stays finite");engine->stop();engine->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(block.getMagnitude(0,0,512)==0,"Stop clears synth voices and effects");
    auto file=root.getChildFile("custom-synth.pulsesound");expect(saveSynthPreset(factory[30],file).wasOk(),"local sound saves atomically");SynthPreset loaded;expect(loadSynthPreset(file,loaded).wasOk()&&loaded.patch==factory[30].patch&&loaded.name==factory[30].name,"local sound reloads without external assets");auto oldHash=SHA256(file).toHexString();auto invalid=factory[0];invalid.patch.cutoff=std::numeric_limits<float>::infinity();expect(saveSynthPreset(invalid,file).failed()&&SHA256(file).toHexString()==oldHash,"invalid sound cannot overwrite a valid patch file");auto bad=synthPresetToJson(factory[0]);bad.getDynamicObject()->setProperty("schema",99);auto previous=loaded.patch;expect(synthPresetFromJson(bad,loaded).failed()&&loaded.patch==previous,"unknown sound schema preserves previous patch");bad=synthPresetToJson(factory[0]);bad["patch"].getDynamicObject()->setProperty("coarse",2.5);expect(synthPresetFromJson(bad,loaded).failed()&&loaded.patch==previous,"fractional oscillator semitone JSON is rejected atomically");
    for(int i=0;i<20;++i){Track track;for(double normal:{0.,.5,1.}){auto value=synthParameterFromNormal(i,normal);expect(setSynthParameter(track,i,value).wasOk(),"synth parameter bounds map to valid settings");expect(std::abs(synthParameterNormal(i,synthParameterValue(track,i))-normal)<.011,"synth parameter readout maps back to its knob position");}}
    Track unchanged;auto old=unchanged.synth;expect(setSynthParameter(unchanged,6,-100).failed()&&unchanged.synth==old,"out-of-range synth edit is atomic");expect(setSynthParameter(unchanged,1,std::numeric_limits<double>::quiet_NaN()).failed()&&unchanged.synth==old,"non-finite synth edit is atomic");
    auto persisted=projectToJson(song);Project restored;expect((int)persisted["schema"]==projectSchema&&projectFromJson(persisted,restored).wasOk()&&restored.tracks[7].synth==t.synth&&restored.tracks[7].instrument==Instrument::fm,"schema 8 retains complete synth state");auto legacySource=demoProject();legacySource.masterSoftClip=true;auto legacy=projectToJson(legacySource);legacy.getDynamicObject()->setProperty("schema",7);for(auto& row:*legacy["tracks"].getArray()){row.getDynamicObject()->removeProperty("synth");row.getDynamicObject()->removeProperty("soundName");}Project migrated;expect(projectFromJson(legacy,migrated).wasOk(),"schema 7 projects migrate with legacy instrument types unchanged");auto original=render(legacySource,assets,root,48000,512),migratedAudio=render(migrated,assets,root,48000,512);equal=true;for(int ch=0;ch<2;++ch)for(int i=0;i<48000;++i)equal&=original.getSample(ch,i)==migratedAudio.getSample(ch,i);expect(equal,"legacy project migration preserves original generator audio exactly");
    auto invalidProject=projectToJson(song);(*invalidProject["tracks"].getArray())[7].getDynamicObject()->removeProperty("synth");auto beforeTitle=restored.title;expect(projectFromJson(invalidProject,restored).failed()&&restored.title==beforeTitle,"schema 8 synth channel requires complete patch state");
    t.synth.cutoff=std::numeric_limits<float>::quiet_NaN();String warnings;auto playback=std::make_unique<Playback>();expect(compilePlayback(song,assets,root,*playback,warnings).failed(),"invalid synth cannot enter an audio snapshot");
}
